UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "A verb is made of blocks", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "Korean verbs are built from blocks. 먹 means eat, and 어요 makes it polite.", "example": {"sentence": "먹어요.", "translation": "eat", "tts": true, "words": [{"parts": [{"text": "먹", "meaning": "eat", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "One block makes the past", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "To talk about the past, put 었 in the middle.", "example": {"sentence": "먹었어요.", "translation": "ate", "tts": true, "words": [{"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "었", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "New word: 어제", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "어제 means yesterday. When you hear it, the verb is usually in the past.", "example": {"sentence": "어제 먹었어요.", "translation": "I ate yesterday.", "tts": true, "words": [{"parts": [{"text": "어제", "meaning": "yesterday", "highlight": true}]}, {"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "었", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I ate bread yesterday.", "sentence": "저는 어제 빵을 [ ? ].", "options": ["먹어요", "먹었어요"], "answer": "먹었어요", "feedback": {"correct": "Yes! 어제 means yesterday, and 었 makes it past.", "incorrect": "어제 means yesterday. 먹어요 is now, so look for the 었 block."}}]}}, {"step_type": "concept", "title": "Same block, new verb", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "읽 means read. Add the same 었 block to talk about the past.", "example": {"sentence": "저는 어제 책을 읽었어요.", "translation": "I read a book yesterday.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "어제", "meaning": "yesterday", "highlight": false}]}, {"parts": [{"text": "책을", "meaning": "book (object)", "highlight": false}]}, {"parts": [{"text": "읽", "meaning": "read", "highlight": false}, {"text": "었", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Minsu read a book yesterday.", "sentence": "민수는 어제 책을 [ ? ].", "options": ["읽었어요", "읽어요"], "answer": "읽었어요", "feedback": {"correct": "Right! 어제 is your clue. 읽었어요 is past.", "incorrect": "어제 means yesterday, so use the form with 었."}}]}}, {"step_type": "concept", "title": "Sometimes it is 았", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "찾 means find. Its vowel is ㅏ, so the block is 았, not 었.", "example": {"sentence": "찾았어요.", "translation": "found", "tts": true, "words": [{"parts": [{"text": "찾", "meaning": "find", "highlight": false}, {"text": "았", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "How to choose", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "Check the verb's last vowel. ㅏ or ㅗ takes 았, and other vowels take 었.", "example": {"sentence": "유미는 가방을 찾았어요.", "translation": "Yumi found her bag.", "tts": true, "words": [{"parts": [{"text": "유미는", "meaning": "Yumi (topic)", "highlight": false}]}, {"parts": [{"text": "가방을", "meaning": "bag (object)", "highlight": false}]}, {"parts": [{"text": "찾", "meaning": "find", "highlight": false}, {"text": "았", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Yumi found her bag.", "sentence": "유미는 가방을 [ ? ].", "options": ["찾었어요", "찾았어요"], "answer": "찾았어요", "feedback": {"correct": "Great! The vowel in 찾 is ㅏ, so it takes 았.", "incorrect": "Check the vowel in 찾. It is ㅏ, so use 았."}}]}}, {"step_type": "concept", "title": "A small note", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "Verbs ending in a vowel, like 가요, change shape in the past. For now, just use verbs like 먹.", "example": null, "tap_to_assemble": false}}, {"step_type": "completion", "title": "Past Tense Learned!", "instruction": "Next, practice it with the rabbit.", "content": {"text": "Put 았 or 었 before 어요 to talk about the past.\nㅏ or ㅗ → 았 (찾았어요). Other vowels → 었 (먹었어요).", "highlights": ["았", "었", "어제"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u3-l2-learn';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Quick recap", "instruction": "", "content": {"character": "rabbit", "mood": "happy", "explanation": "Last vowel ㅏ or ㅗ takes 았. Other vowels take 었.", "example": {"sentence": "먹었어요.", "translation": "ate", "tts": true, "words": [{"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "었", "meaning": "past", "highlight": true}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "intro", "title": "Vocabulary: Yesterday", "instruction": "Tap and listen. You'll use all of these today.", "content": {"explanation": {"title": "Words for today"}, "sentences": [{"korean": "어제", "english": "Yesterday", "tts": true, "chunks": [{"display": "어제", "tokens": [{"text": "어제", "meaning": "yesterday"}]}]}, {"korean": "먹었어요", "english": "Ate", "tts": true, "chunks": [{"display": "먹었어요", "tokens": [{"text": "먹었어요", "meaning": "ate"}]}]}, {"korean": "읽었어요", "english": "Read (past)", "tts": true, "chunks": [{"display": "읽었어요", "tokens": [{"text": "읽었어요", "meaning": "read (past)"}]}]}, {"korean": "있었어요", "english": "Was (at a place)", "tts": true, "chunks": [{"display": "있었어요", "tokens": [{"text": "있었어요", "meaning": "was (at a place)"}]}]}, {"korean": "없었어요", "english": "Didn't have", "tts": true, "chunks": [{"display": "없었어요", "tokens": [{"text": "없었어요", "meaning": "didn't have"}]}]}, {"korean": "찾았어요", "english": "Found", "tts": true, "chunks": [{"display": "찾았어요", "tokens": [{"text": "찾았어요", "meaning": "found"}]}]}, {"korean": "앉았어요", "english": "Sat", "tts": true, "chunks": [{"display": "앉았어요", "tokens": [{"text": "앉았어요", "meaning": "sat"}]}]}, {"korean": "받았어요", "english": "Received", "tts": true, "chunks": [{"display": "받았어요", "tokens": [{"text": "받았어요", "meaning": "received"}]}]}]}}, {"step_type": "practice", "title": "Round 1: Spot the past", "instruction": "Is it now or the past? 어제 and 지금 are your clues.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I ate bread yesterday.", "sentence": "저는 어제 빵을 [ ? ].", "options": ["먹어요", "먹었어요"], "answer": "먹었어요", "feedback": {"correct": "Correct! 어제 means past, so 먹었어요."}}, {"type": "fill_blank", "instruction": "Minsu read a book yesterday.", "sentence": "민수는 어제 책을 [ ? ].", "options": ["읽었어요", "읽어요"], "answer": "읽었어요", "feedback": {"correct": "Right! 어제 means past, so 읽었어요."}}, {"type": "fill_blank", "instruction": "Yumi was at home yesterday.", "sentence": "유미는 어제 집에 [ ? ].", "options": ["있어요", "있었어요"], "answer": "있었어요", "feedback": {"correct": "Great! 어제 means past, so 있었어요."}}, {"type": "fill_blank", "instruction": "Minsu is at home now.", "sentence": "민수는 지금 집에 [ ? ].", "options": ["있어요", "있었어요"], "answer": "있어요", "feedback": {"correct": "Nice catch! 지금 means now, so 있어요."}}, {"type": "fill_blank", "instruction": "I didn't have time yesterday.", "sentence": "저는 어제 시간이 [ ? ].", "options": ["없었어요", "없어요"], "answer": "없었어요", "feedback": {"correct": "Perfect! 어제 means past, so 없었어요."}}]}}, {"step_type": "practice", "title": "Round 2: 았 or 었?", "instruction": "Look at the last vowel of the verb.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I ate bread.", "sentence": "저는 빵을 [ ? ].", "options": ["먹었어요", "먹았어요"], "answer": "먹었어요", "feedback": {"correct": "Correct! The vowel in 먹 is ㅓ, so it takes 었."}}, {"type": "fill_blank", "instruction": "Yumi found her bag.", "sentence": "유미는 가방을 [ ? ].", "options": ["찾었어요", "찾았어요"], "answer": "찾았어요", "feedback": {"correct": "Great! The vowel in 찾 is ㅏ, so it takes 았."}}, {"type": "fill_blank", "instruction": "Minsu read a book.", "sentence": "민수는 책을 [ ? ].", "options": ["읽았어요", "읽었어요"], "answer": "읽었어요", "feedback": {"correct": "Right! The vowel in 읽 is ㅣ, so it takes 었."}}, {"type": "fill_blank", "instruction": "I sat in the café.", "sentence": "저는 카페에 [ ? ].", "options": ["앉았어요", "앉었어요"], "answer": "앉았어요", "feedback": {"correct": "Perfect! The vowel in 앉 is ㅏ, so it takes 았."}}, {"type": "fill_blank", "instruction": "Minsu received a book yesterday.", "sentence": "민수는 어제 책을 [ ? ].", "options": ["받었어요", "받았어요"], "answer": "받았어요", "feedback": {"correct": "Correct! The vowel in 받 is ㅏ, so it takes 았."}}, {"type": "fill_blank", "instruction": "Yumi was at home yesterday.", "sentence": "유미는 어제 집에 [ ? ].", "options": ["있었어요", "있았어요"], "answer": "있었어요", "feedback": {"correct": "Right! The vowel in 있 is ㅣ, so it takes 었."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I ate bread.\" Split the verb, 았/었 and the ending. 먹 has ㅓ, so use 었.", "contentObj": {"sentence": "저는 빵을 먹었어요.", "translation": "I ate bread.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["빵을"], "correct_turtle": ["빵을"], "turtle_explanation": "Keep '빵을' as one block — it is not this lesson's focus."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["먹었어요"], "correct_turtle": ["먹", "었", "어요"], "turtle_explanation": "'었' marks the past. After ㅏ or ㅗ use 았, otherwise use 었."}], "options": [{"id": "o1", "text": "었", "mode": "turtle"}, {"id": "o2", "text": "았", "mode": "turtle"}, {"id": "o3", "text": "먹", "mode": "turtle"}, {"id": "o4", "text": "먹았어요", "mode": "rabbit"}, {"id": "o5", "text": "빵을", "mode": "rabbit"}, {"id": "o6", "text": "어요", "mode": "turtle"}, {"id": "o7", "text": "빵을", "mode": "turtle"}, {"id": "o8", "text": "먹었어요", "mode": "rabbit"}, {"id": "o9", "text": "저는", "mode": "turtle"}, {"id": "o10", "text": "저는", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Yumi found her bag.\" Split the verb, 았/었 and the ending.", "contentObj": {"sentence": "유미는 가방을 찾았어요.", "translation": "Yumi found her bag.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["유미는"], "correct_turtle": ["유미는"], "turtle_explanation": "Keep '유미는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["가방을"], "correct_turtle": ["가방을"], "turtle_explanation": "Keep '가방을' as one block — it is not this lesson's focus."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["찾았어요"], "correct_turtle": ["찾", "았", "어요"], "turtle_explanation": "'았' marks the past. After ㅏ or ㅗ use 았, otherwise use 었."}], "options": [{"id": "o1", "text": "찾았어요", "mode": "rabbit"}, {"id": "o2", "text": "찾었어요", "mode": "rabbit"}, {"id": "o3", "text": "가방을", "mode": "turtle"}, {"id": "o4", "text": "찾", "mode": "turtle"}, {"id": "o5", "text": "았", "mode": "turtle"}, {"id": "o6", "text": "었", "mode": "turtle"}, {"id": "o7", "text": "어요", "mode": "turtle"}, {"id": "o8", "text": "유미는", "mode": "rabbit"}, {"id": "o9", "text": "유미는", "mode": "turtle"}, {"id": "o10", "text": "가방을", "mode": "rabbit"}]}}, {"step_type": "intro", "title": "Conversation", "instruction": "Take a break and listen. You know these words now.", "content": {"explanation": {"title": "What did you do?"}, "sentences": [{"korean": "민수: 유미 씨, 어제 뭐 했어요?", "english": "Minsu: Yumi, what did you do yesterday?", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "유미", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}]}, {"display": "씨,", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}]}, {"display": "어제", "tokens": [{"text": "어제", "meaning": "yesterday"}]}, {"display": "뭐", "tokens": [{"text": "뭐", "meaning": "what"}]}, {"display": "했어요?", "tokens": [{"text": "했어요", "meaning": "did (past)"}]}]}, {"korean": "유미: 저는 집에서 책을 읽었어요. 민수 씨는 뭐 했어요?", "english": "Yumi: I read a book at home. Minsu, what did you do?", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "집에서", "tokens": [{"text": "집", "meaning": "home"}, {"text": "에서", "meaning": "action place marker"}]}, {"display": "책을", "tokens": [{"text": "책", "meaning": "book"}, {"text": "을", "meaning": "object marker"}]}, {"display": "읽었어요.", "tokens": [{"text": "읽", "meaning": "read"}, {"text": "었", "meaning": "past"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "민수", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}]}, {"display": "씨는", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}, {"text": "는", "meaning": "topic marker"}]}, {"display": "뭐", "tokens": [{"text": "뭐", "meaning": "what"}]}, {"display": "했어요?", "tokens": [{"text": "했어요", "meaning": "did (past)"}]}]}, {"korean": "민수: 저는 카페에 있었어요. 빵을 먹었어요.", "english": "Minsu: I was at a café. I ate bread.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "카페에", "tokens": [{"text": "카페", "meaning": "café"}, {"text": "에", "meaning": "place marker"}]}, {"display": "있었어요.", "tokens": [{"text": "있", "meaning": "there is / have / be at"}, {"text": "었", "meaning": "past"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "빵을", "tokens": [{"text": "빵", "meaning": "bread"}, {"text": "을", "meaning": "object marker"}]}, {"display": "먹었어요.", "tokens": [{"text": "먹", "meaning": "eat"}, {"text": "었", "meaning": "past"}, {"text": "어요", "meaning": "polite ending"}]}]}]}}, {"step_type": "practice", "title": "Round 3: All together", "instruction": "Now with 에서 and 안 from Unit 2. You've got this!", "content": {"exercises": [{"type": "fill_blank", "instruction": "Minsu ate bread at a café.", "sentence": "민수는 카페에서 빵을 [ ? ].", "options": ["먹았어요", "먹었어요"], "answer": "먹었어요", "feedback": {"correct": "Yes! 먹 + 었"}}, {"type": "fill_blank", "instruction": "Yumi read a book at the library.", "sentence": "유미는 도서관에서 책을 [ ? ].", "options": ["읽었어요", "읽았어요"], "answer": "읽었어요", "feedback": {"correct": "Nice! 읽 + 었"}}, {"type": "fill_blank", "instruction": "I was at school yesterday.", "sentence": "저는 어제 학교에 [ ? ].", "options": ["있었어요", "있았어요"], "answer": "있었어요", "feedback": {"correct": "Good! 있 + 었"}}, {"type": "fill_blank", "instruction": "I received a book today.", "sentence": "저는 오늘 책을 [ ? ].", "options": ["받었어요", "받았어요"], "answer": "받았어요", "feedback": {"correct": "Great! 받 + 았"}}, {"type": "fill_blank", "instruction": "Yumi didn't eat bread yesterday.", "sentence": "유미는 어제 빵을 안 [ ? ].", "options": ["먹어요", "먹었어요"], "answer": "먹었어요", "feedback": {"correct": "Perfect! 안 stays, and 먹 + 었"}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #3", "instruction": "Build the sentence: \"Minsu was at home yesterday.\" Split the verb too.", "contentObj": {"sentence": "민수는 어제 집에 있었어요.", "translation": "Minsu was at home yesterday.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["민수는"], "correct_turtle": ["민수는"], "turtle_explanation": "Keep '민수는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["어제"], "correct_turtle": ["어제"], "turtle_explanation": "Keep '어제' as one block — it is not this lesson's focus."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["집에"], "correct_turtle": ["집에"], "turtle_explanation": "Keep '집에' as one block — it is not this lesson's focus."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["있었어요"], "correct_turtle": ["있", "었", "어요"], "turtle_explanation": "'었' marks the past. After ㅏ or ㅗ use 았, otherwise use 었."}], "options": [{"id": "o1", "text": "민수는", "mode": "rabbit"}, {"id": "o2", "text": "았", "mode": "turtle"}, {"id": "o3", "text": "민수는", "mode": "turtle"}, {"id": "o4", "text": "어제", "mode": "rabbit"}, {"id": "o5", "text": "어요", "mode": "turtle"}, {"id": "o6", "text": "있았어요", "mode": "rabbit"}, {"id": "o7", "text": "있었어요", "mode": "rabbit"}, {"id": "o8", "text": "집에", "mode": "rabbit"}, {"id": "o9", "text": "어제", "mode": "turtle"}, {"id": "o10", "text": "었", "mode": "turtle"}, {"id": "o11", "text": "있", "mode": "turtle"}, {"id": "o12", "text": "집에", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #4", "instruction": "Build the sentence: \"Yumi read a book at the library.\"", "contentObj": {"sentence": "유미는 도서관에서 책을 읽었어요.", "translation": "Yumi read a book at the library.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["유미는"], "correct_turtle": ["유미는"], "turtle_explanation": "Keep '유미는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["도서관에서"], "correct_turtle": ["도서관에서"], "turtle_explanation": "Keep '도서관에서' as one block — it is not this lesson's focus."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["책을"], "correct_turtle": ["책을"], "turtle_explanation": "Keep '책을' as one block — it is not this lesson's focus."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["읽었어요"], "correct_turtle": ["읽", "었", "어요"], "turtle_explanation": "'었' marks the past. After ㅏ or ㅗ use 았, otherwise use 었."}], "options": [{"id": "o1", "text": "도서관에서", "mode": "rabbit"}, {"id": "o2", "text": "어요", "mode": "turtle"}, {"id": "o3", "text": "았", "mode": "turtle"}, {"id": "o4", "text": "책을", "mode": "turtle"}, {"id": "o5", "text": "유미는", "mode": "turtle"}, {"id": "o6", "text": "유미는", "mode": "rabbit"}, {"id": "o7", "text": "읽", "mode": "turtle"}, {"id": "o8", "text": "읽었어요", "mode": "rabbit"}, {"id": "o9", "text": "읽았어요", "mode": "rabbit"}, {"id": "o10", "text": "었", "mode": "turtle"}, {"id": "o11", "text": "도서관에서", "mode": "turtle"}, {"id": "o12", "text": "책을", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #5", "instruction": "Build the sentence: \"Minsu found his bag at school.\"", "contentObj": {"sentence": "민수는 학교에서 가방을 찾았어요.", "translation": "Minsu found his bag at school.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["민수는"], "correct_turtle": ["민수는"], "turtle_explanation": "Keep '민수는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["학교에서"], "correct_turtle": ["학교에서"], "turtle_explanation": "Keep '학교에서' as one block — it is not this lesson's focus."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["가방을"], "correct_turtle": ["가방을"], "turtle_explanation": "Keep '가방을' as one block — it is not this lesson's focus."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["찾았어요"], "correct_turtle": ["찾", "았", "어요"], "turtle_explanation": "'았' marks the past. After ㅏ or ㅗ use 았, otherwise use 었."}], "options": [{"id": "o1", "text": "찾었어요", "mode": "rabbit"}, {"id": "o2", "text": "학교에서", "mode": "turtle"}, {"id": "o3", "text": "았", "mode": "turtle"}, {"id": "o4", "text": "찾", "mode": "turtle"}, {"id": "o5", "text": "찾았어요", "mode": "rabbit"}, {"id": "o6", "text": "가방을", "mode": "rabbit"}, {"id": "o7", "text": "어요", "mode": "turtle"}, {"id": "o8", "text": "민수는", "mode": "turtle"}, {"id": "o9", "text": "민수는", "mode": "rabbit"}, {"id": "o10", "text": "가방을", "mode": "turtle"}, {"id": "o11", "text": "었", "mode": "turtle"}, {"id": "o12", "text": "학교에서", "mode": "rabbit"}]}}, {"step_type": "completion", "title": "You Did It!", "instruction": "Great! You can now say what you did in Korean.", "content": {"text": "You've practiced the past with 았/었어요.\nLast vowel ㅏ or ㅗ → 았 (찾았어요). Other vowels → 었 (먹었어요).\nVerbs like 가요 change shape in the past, so we skip them for now.", "highlights": ["았", "었", "어제"]}}]}$lsn$::jsonb
